//! Commands on a task aggregate. Ids and token hashes are generated by the caller (the server),
//! so the decider stays deterministic and free of IO or randomness.

use serde_json::Value;

use crate::model::{
    ActivityKind, CriterionVerdict, Id, LeaseKind, LinkKind, QuestionRef, ReviewVerdict, TokenHash,
};

/// Maximum size of an `activity.reported` body and of a question body (§12).
pub const MAX_REPORT_BYTES: usize = 4096;

#[derive(Debug, Clone, PartialEq)]
pub enum Command {
    /// `claim` — implementer (work lease) or reviewer (review lease).
    Claim {
        kind: LeaseKind,
        token_hash: TokenHash,
        attempt_id: Id,
    },
    Heartbeat {
        token_hash: Option<TokenHash>,
    },
    Report {
        token_hash: Option<TokenHash>,
        kind: ActivityKind,
        body: String,
        trace_id: Option<String>,
    },
    Ask {
        token_hash: Option<TokenHash>,
        question_id: Id,
        body: String,
        blocking: bool,
        options: Option<Value>,
        handoff_note: Option<String>,
    },
    Answer {
        question: QuestionRef,
        answer: String,
    },
    Release {
        token_hash: Option<TokenHash>,
        handoff_note: String,
    },
    /// Sweeper: the lease passed `expires_at` without a heartbeat.
    ExpireLease,
    SubmitForTest {
        token_hash: Option<TokenHash>,
        commit_sha: String,
        branch: Option<String>,
        test_run_id: Id,
    },
    /// Verifier (test_gate = command) or human (test_gate = human) result.
    CompleteTest {
        test_run_id: Id,
        passed: bool,
        protected_path_violation: bool,
    },
    SubmitReview {
        token_hash: Option<TokenHash>,
        review_id: Id,
        commit_sha: String,
        verdict: ReviewVerdict,
        per_criterion: Vec<CriterionVerdict>,
        comment: Option<String>,
        /// Id of the human question opened if this review makes the task fail.
        failure_question_id: Id,
        /// Summary of the attempts, written into that question.
        failure_summary: String,
    },
    /// Fan-out after a spec version was approved.
    SpecApproved {
        version: i32,
    },
    Repin {
        token_hash: Option<TokenHash>,
        to_version: i32,
    },
    Cancel {
        reason: Option<String>,
    },
    /// UI patch with optimistic concurrency.
    Update {
        expected_version: i32,
        title: Option<String>,
        priority: Option<i32>,
    },
    /// Add a link from this task to `to`.
    AddLink {
        to: Id,
        kind: LinkKind,
    },
}

impl Command {
    pub fn name(&self) -> &'static str {
        match self {
            Command::Claim { .. } => "claim",
            Command::Heartbeat { .. } => "heartbeat",
            Command::Report { .. } => "report",
            Command::Ask { .. } => "ask",
            Command::Answer { .. } => "answer",
            Command::Release { .. } => "release",
            Command::ExpireLease => "expire_lease",
            Command::SubmitForTest { .. } => "submit_for_test",
            Command::CompleteTest { .. } => "complete_test",
            Command::SubmitReview { .. } => "submit_review",
            Command::SpecApproved { .. } => "spec_approved",
            Command::Repin { .. } => "repin",
            Command::Cancel { .. } => "cancel",
            Command::Update { .. } => "update",
            Command::AddLink { .. } => "add_link",
        }
    }
}

/// Input of `decide_create` — a new task.
#[derive(Debug, Clone, PartialEq)]
pub struct NewTask {
    pub task_id: Id,
    pub project_id: Id,
    pub title: String,
    pub spec_id: Id,
    pub spec_version: i32,
    pub parent_id: Option<Id>,
    pub priority: i32,
    pub blocked_by: Vec<Id>,
    pub discovered_from: Option<Id>,
}
